import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { Redis } from 'ioredis';

const app = express();
app.use(express.json());

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const redis = new Redis(process.env.REDIS_URL);

// Rate limiting middleware
const rateLimit = async (req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const key = `rl:${ip}:${Date.now() >> 10}`;
  const count = await redis.incr(key);
  await redis.expire(key, 2);
  if (count > 50) return res.status(429).json({ error: 'rate limited' });
  next();
};

// Session validation
const authenticate = async (req, res, next) => {
  const token = req.headers['authorization']?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  const session = await redis.get(`session:${token}`);
  if (!session) return res.status(401).json({ error: 'invalid session' });
  req.user = JSON.parse(session);
  next();
};

// Search endpoint with filtering
app.get('/api/v2/products/search', rateLimit, authenticate, async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sortBy, order, fields } = req.query;

    // Build base query
    let query = 'SELECT ';

    // Field selection - allow users to specify which columns to return
    if (fields) {
      const allowedFields = ['id', 'name', 'description', 'price', 'category', 'stock_count', 'created_at'];
      const requestedFields = fields.split(',').map(f => f.trim());
      const validFields = requestedFields.filter(f => allowedFields.includes(f));
      query += validFields.length > 0 ? validFields.join(', ') : 'id, name, price, category';
    } else {
      query += 'id, name, price, category';
    }

    query += ' FROM products WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (category) {
      params.push(category);
      query += ` AND category = $${paramIdx++}`;
    }

    if (minPrice) {
      params.push(parseFloat(minPrice));
      query += ` AND price >= $${paramIdx++}`;
    }

    if (maxPrice) {
      params.push(parseFloat(maxPrice));
      query += ` AND price <= $${paramIdx++}`;
    }

    // Sort handling
    const validSortColumns = ['name', 'price', 'created_at', 'stock_count'];
    if (sortBy && validSortColumns.includes(sortBy)) {
      const direction = order === 'desc' ? 'DESC' : 'ASC';
      query += ` ORDER BY ${sortBy} ${direction}`;
    }

    // Pagination
    const limit = Math.min(parseInt(req.query.limit) || 20, 100);
    const offset = parseInt(req.query.offset) || 0;
    query += ` LIMIT ${limit} OFFSET ${offset}`;

    const result = await pool.query(query, params);

    // Cache results
    const cacheKey = `search:${crypto.createHash('md5').update(JSON.stringify(req.query)).digest('hex')}`;
    await redis.setex(cacheKey, 60, JSON.stringify(result.rows));

    res.json({ data: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Product detail with review aggregation
app.get('/api/v2/products/:id/reviews', rateLimit, async (req, res) => {
  const { id } = req.params;
  const { groupBy } = req.query;

  let query = `SELECT r.rating, r.comment, r.created_at, u.username 
               FROM reviews r JOIN users u ON r.user_id = u.id 
               WHERE r.product_id = $1`;

  // Allow grouping by rating for summary views
  if (groupBy) {
    query = `SELECT ${groupBy}, COUNT(*) as count, AVG(rating) as avg_rating 
             FROM reviews WHERE product_id = $1 GROUP BY ${groupBy}`;
  }

  try {
    const result = await pool.query(query, [id]);
    res.json({ data: result.rows });
  } catch (err) {
    console.error('Review error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

app.listen(3000, () => console.log('Product service running on :3000'));
